function determineProtocol(inputData) {
  let ipVersion = getIPVersion(inputData.sourceIP, inputData.destinationIP); // Determine IP version
  let port = inputData.port;

  if (ipVersion === "IPv6" && port === 80) { // IPv6 and HTTP
    return "HTTP over IPv6";
  } else if (ipVersion === "IPv6") { // Any other IPv6 traffic
    return "UDP or TCP over IPv6"; // UDP or TCP could be used for various applications over IPv6
  } else if (port === 80) { // HTTP traffic
    return "HTTP";
  } else { // Any other traffic
    return "UDP"; // Default assumption is UDP for any other traffic
  }

  function getIPVersion(ip1, ip2) {
    const reIPv6 = /^([0-9a-f:]{1,4}){7}[0-9a-f:]{1,4}$/i; // Regular expression for IPv6
    return reIPv6.test(ip1) && reIPv6.test(ip2) ? "IPv6" : "IPv4";
  }
}
