```javascript import { useState } from 'react';

const TemperatureConverter = () => {
  // State variables for input temperature and selected unit
  const [inputTemp, setInputTemp] = useState(0);
  const [unit, setUnit] = useState('celsius');

  // Function to handle temperature conversion based on the selected unit
  const handleConvert = () => {
    if (unit === 'celsius') {
      setInputTemp((prevTemp) => (prevTemp * 9 / 5) + 32);
      setUnit('fahrenheit');
    } else if (unit === 'fahrenheit') {
      setInputTemp((prevTemp) => ((prevTemp - 32) * 5 / 9));
      setUnit('celsius');
    } else if (unit === 'kelvin') {
      setInputTemp((prevTemp) => prevTemp - 273.15);
      setUnit('celsius');
    }
  };

  return (
    <div>
      <label htmlFor="temperature">Enter temperature:</label>
      <input
        type="number"
        id="temperature"
        value={inputTemp}
        onChange={(e) => setInputTemp(Number(e.target.value))}
      />
      <button onClick={handleConvert}>Convert</button>
      <p>
        {inputTemp} {unit === 'celsius' ? '°C' : unit === 'fahrenheit' ? '°F' : 'K'}
      </p>
      <button onClick={() => setUnit('celsius')}>Convert to Celsius</button>
      <button onClick={() => setUnit('fahrenheit')}>Convert to Fahrenheit</button>
      <button onClick={() => setUnit('kelvin')}>Convert to Kelvin</button>
    </div>
  );
};

export default TemperatureConverter; ```

