namespace TextClassificationWithNaiveBayes
{
    public static class Program
    {
        static void Main(string[] args)
        {
            // Load dataset from a tab-separated file (labels in the first column)
            var dataPath = @"path\to\your\dataset.tsv";
            var data = CsvFileReader<string[]>.Default.Read(dataPath).ToList();

            // Split the data into features (words) and targets (categories)
            var features = data.Select(x => x[1].Split(' ')).ToArray();
            var labels = data.Select(x => int.Parse(x[0])).ToArray();

            // Transform the dataset into a bag-of-words representation using CountVectorizer
