    const lines = text.split('\n');
    let lastLine = lines[lines.length - 1].trim();
    const words = lastLine.split(' ');

    if (words.length > 1) {
      lastLine += ' ' + words[words.length - 1];
      setText(text.substring(0, text.lastIndexOf(lastLine)) + lastLine + '\n' + text.substr(text.lastIndexOf(lastLine) + lastLine.length));
    }
  };

  React.useEffect(() => {
    removeWidows();
  }, [children]);

  return <p>{text}</p>;
};

OrphanRemover.propTypes = {
  children: PropTypes.node.isRequired,
};

export default OrphanRemover;
```

